// ECP5-P1 HDMI unit test top:
//   (a) a bare tmds_enc channel (CH 0) driven cycle by cycle -> known-vector test
//   (b) hdmi_tx (ACR CTS 25000) -> ecp5_tmds_ser (ODDRX1F) -> 4 pad bits, with the video
//       stream and the audio samples generated by the testbench (colour bars, 640x480).
module hdmi_unit_top (
    input        clk_pix, clk_x5,
    input        rst,
    // (a)
    input  [2:0] e_mode,
    input  [7:0] e_d,
    input  [1:0] e_c,
    input  [3:0] e_t,
    output [9:0] e_q,
    // (b)
    input  [7:0] r, g, b,
    input        hs_n, vs_n, de,
    input        aud_we,
    input [15:0] aud_l, aud_r,
    output [3:0] tmds_q,
    output [9:0] t0, t1, t2,
    output       locked, aud_overflow
);
    tmds_enc #(.CH(0)) u_enc (.clk(clk_pix), .mode(e_mode), .d(e_d), .c(e_c), .t(e_t), .q(e_q));

    hdmi_tx #(.ACR_CTS_VAL(25000)) u_tx (
        .clk(clk_pix), .rst(rst), .r(r), .g(g), .b(b), .hs_n(hs_n), .vs_n(vs_n), .de(de),
        .aud_we(aud_we), .aud_l(aud_l), .aud_r(aud_r),
        .tmds0(t0), .tmds1(t1), .tmds2(t2), .locked(locked), .aud_overflow(aud_overflow));

    reg [2:0] rs = 3'b111;
    always @(posedge clk_x5 or posedge rst) if (rst) rs <= 3'b111; else rs <= {rs[1:0], 1'b0};
    ecp5_tmds_ser u_ser (.clk_pix(clk_pix), .clk_x5(clk_x5), .rst_x5(rs[2]),
                         .t0(t0), .t1(t1), .t2(t2), .q(tmds_q));
endmodule
